from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []
    for op in ops:
        kind = op[0]
        if kind == 'put':
            _, t, key, value = op
            if key in cache:
                # remove existing entry (regardless of expiry), will re-add
                cache.pop(key)
            else:
                if len(cache) >= capacity:
                    # evict least recently used
                    cache.popitem(last=False)
            cache[key] = (value, t)
            # move to end (most recently used)
            cache.move_to_end(key)
        elif kind == 'get':
            _, t, key = op
            if key not in cache:
                results.append(-1)
            else:
                value, write_time = cache[key]
                if t >= write_time + ttl:
                    # expired, treat as absent, no order change
                    results.append(-1)
                else:
                    results.append(value)
                    cache.move_to_end(key)
        else:
            raise ValueError("Unknown op type: " + str(kind))
    return results

